raised = False
try:
    assert_image_loaded(None, 'brak.jpg')
except FileNotFoundError:
    raised = True
assert raised, 'Dla img is None oczekiwany był FileNotFoundError, a nic nie zostało rzucone.'

try:
    assert_image_loaded(None, '/tmp/nieistnieje.png')
except FileNotFoundError as e:
    assert '/tmp/nieistnieje.png' in str(e), f'Wiadomość wyjątku powinna zawierać ścieżkę, dostałem: {e!r}'
else:
    raise AssertionError('FileNotFoundError nie został rzucony')

